grid_tibble <- tibble(state = input) |>
  separate_rows(state, sep = "\n")

row_length <- str_length(grid_tibble$state[[1]])
column_height <- nrow(grid_tibble)

grid_tibble <- grid_tibble |>
  separate_rows(state, sep = "") |>
  filter(state != "") |>
  mutate(position = 0 + 0i) |> 
  mutate(new_state = state)

for (k in 1:row_length) {
  for (j in 1:column_height) {
    grid_tibble$position[k + row_length * (j - 1)] <- complex(real = k, imaginary = j)
  }
  
}

start_rolls_count <- sum((grid_tibble |> mutate(rolls = ifelse(state == "@", 1, 0)))$rolls)

update_states <- function(states) {
  states <- states |> mutate(state = ifelse(new_state == "x", ".", new_state), new_state = state)
  
  
  for (k in 1:nrow(states)) {
    if(states$state[[k]] != "@") next
    
    neighbours <- states$position[[k]] + c(complex(real = 0, imaginary = 1),
                                           complex(real = 0, imaginary = -1),
                                           complex(real = 1, imaginary = 0),
                                           complex(real = -1, imaginary = 0),
                                           complex(real = 1, imaginary = 1),
                                           complex(real = 1, imaginary = -1),
                                           complex(real = -1, imaginary = 1),
                                           complex(real = -1, imaginary = -1))
    
    roll_neighbours <- sum((filter(states, position %in% neighbours) |> mutate(rolls = ifelse(state == "@", 1, 0)))$rolls)
    
    ifelse(roll_neighbours >= 4, states$new_state[[k]] <- states$new_state[[k]], states$new_state[[k]] <- "x")
  }
  
  return(states)
}

answer1 <- nrow((update_states(grid_tibble) |> filter(new_state == "x")))


finish <- 0
count <- 0

while (finish <= 10) {
  grid_tibble <- update_states(grid_tibble)
  if(all(grid_tibble$state == grid_tibble$new_state)) break()
  count <- count + 1
  print(count)
}

answer2 <- start_rolls_count - sum((grid_tibble |> mutate(rolls = ifelse(state == "@", 1, 0)))$rolls)